const C=window.MBT_CONFIG||{}, Q=window.MBT_QUOTES||[], $=s=>document.querySelector(s), root=$('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(x,d=0)=>Number.isFinite(Number(x))?Number(x):d, clamp=(x,a,b)=>Math.min(b,Math.max(a,x)), fmt=x=>Math.round(x).toLocaleString('en-IN'), rid=()=>crypto.randomUUID?.()||String(Date.now()+Math.random());
const dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`, today=()=>dateKey(), shift=(n,d=new Date())=>{let a=new Date(d);a.setDate(a.getDate()+n);return dateKey(a)}, timeMin=()=>new Date().getHours()*60+new Date().getMinutes(), mins=t=>{const [h,m]=t.split(':').map(Number);return h*60+m}, clock=t=>{const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h<12?'AM':'PM'}`};
const defaults=()=>({profile:null,goal:null,meals:[{id:'morning',name:'Morning meal',time:'11:00'},{id:'afternoon',name:'Afternoon meal',time:'16:00'},{id:'evening',name:'Evening meal',time:'19:00'},{id:'night',name:'Night meal',time:'23:00'}],prefs:{theme:'dark',water:2500,mealAlerts:false,waterAlerts:false,quoteAlerts:false,mealBefore:30,repeat:30,waterRepeat:60,start:'08:00',end:'23:30',quoteTimes:'08:00,13:00,18:00,21:00',categories:['Discipline','Psychology','Physique','Bollywood','Hollywood','Money','Betrayal','Power','Web series','Trending India','Trending world']},days:{},favoriteFoods:[],favorites:[],quoteSeen:[]});
let s=defaults(), user=null, firebase=null, demo=false, tab='home', step=1, selectedDate=today(), quoteId=null, analysis=null, aiError='', busy=false, recorded=null, recorder=null, stream=null, foodDraft='', chosenMeal='', fileDraft=null, syncTimer, pushTimer, toastTimer, initError='', monthOffset=0, qFilter='All', quoteSelection=null;
const storageKey=()=>`mbt-v1-${demo?'demo':user?.uid||'guest'}`;function readLocal(){try{let a=JSON.parse(localStorage.getItem(storageKey()));if(a)s={...defaults(),...a,prefs:{...defaults().prefs,...a.prefs}}}catch{}}
function persist(){try{localStorage.setItem(storageKey(),JSON.stringify(s))}catch{toast('Local storage unavailable.')}if(user&&firebase){clearTimeout(syncTimer);syncTimer=setTimeout(saveCloud,450)}if(user&&C.apiBase){clearTimeout(pushTimer);pushTimer=setTimeout(syncPush,650)}}
function day(k=today()){return s.days[k]||(s.days[k]={food:[],water:[],status:{},weight:null})}function getDay(k){return s.days[k]||{food:[],water:[],status:{},weight:null}}
const total=d=>d.food.reduce((a,f)=>{for(const k of ['kcal','protein','carbs','fat','fiber','sugar','sodium','calcium','iron'])a[k]+=num(f[k]);return a},{kcal:0,protein:0,carbs:0,fat:0,fiber:0,sugar:0,sodium:0,calcium:0,iron:0});const water=d=>d.water.reduce((a,x)=>a+num(x.ml),0);
const bmi=(w,h)=>w/(h/100)**2, cat=b=>b<18.5?'Underweight':b<25?'Healthy range':b<30?'Overweight':'Obesity range';
function plan(p,target,pace){const b=bmi(p.weight,p.height),dir=Math.sign(target-p.weight),base=10*p.weight+6.25*p.height-5*p.age, bmr=p.sex==='male'?base+5:p.sex==='female'?base-161:base-78, tdee=Math.round(bmr*num(p.activity,1.2)),delta=dir===1?pace*7700/7:dir===-1?-Math.min(500,pace*7700/7):0,kcal=dir===1?Math.round(tdee+delta):Math.round((Math.max(p.sex==='male'?1500:1200,tdee+delta))/50)*50, protein=Math.round(p.weight*1.4),fat=Math.round(kcal*.28/9),carbs=Math.max(0,Math.round((kcal-protein*4-fat*9)/4));const effectivePace=dir===1?pace:dir===-1?Math.min(pace,Math.max(0,(tdee-kcal))*7/7700):pace;return {target,pace:effectivePace,requestedPace:pace,dir,bmr:Math.round(bmr),tdee,kcal,protein,fat,carbs,fiber:Math.round(kcal/1000*14),days:dir?(effectivePace>0?Math.ceil(Math.abs(target-p.weight)/effectivePace*7):null):0,start:today(),initial:p.weight,bmi:b};}
function logs(){return Object.entries(s.days).filter(([,d])=>d.weight!=null).sort(([a],[b])=>a.localeCompare(b)).map(([date,d])=>({date,w:num(d.weight)}))}function current(){return logs().at(-1)?.w??s.profile?.weight??0}function forecast(){const g=s.goal;if(!g)return null;const list=logs(), recent=list.slice(-14), first=recent[0],last=recent.at(-1), gap=first&&last?(new Date(last.date)-new Date(first.date))/86400000:0, rate=gap>=7?(last.w-first.w)*7/gap*g.dir:null, remaining=Math.max(0,(g.target-current())*g.dir), days=remaining===0?0:rate===null?(g.pace>0?Math.ceil(remaining/g.pace*7):null):rate>0?Math.ceil(remaining/rate*7):null;return {days,rate,remaining,progress:clamp(Math.abs(g.target-g.initial)>0?(current()-g.initial)*g.dir/Math.abs(g.target-g.initial)*100:100,0,100)}}
function status(m,d,k=today()){return d.status[m.id]?.state|| (k<today()?'unconfirmed':k===today()&&timeMin()>=mins(m.time)?'overdue':'pending')}
function toast(t){const e=$('#toast');e.textContent=t;e.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.style.display='none',3500)}
const bar=(v,g,color='var(--green)')=>`<div class="bar"><span style="width:${clamp(g?v/g*100:0,0,100)}%;background:${color}"></span></div>`;
const ICONS={"home":"<path d=\"m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z\"/>","history":"<rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"3\"/><path d=\"M7 3v4m10-4v4M3 10h18m4 4h2m4 0h2m-8 3h2\"/>","food":"<path d=\"m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6z\"/>","mindset":"<path d=\"M4 5h16v11H9l-5 4zM8 9h8m-8 3h5\"/>","profile":"<circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 21v-2a8 8 0 0 1 16 0v2\"/>","sun":"<circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2\"/>","moon":"<path d=\"M20 15A9 9 0 0 1 9 4 9 9 0 1 0 20 15Z\"/>","activity":"<path d=\"M2 12h5l3-7 4 14 3-7h5\"/>","camera":"<path d=\"M4 6h4l2-3h4l2 3h4v14H4z\"/><circle cx=\"12\" cy=\"13\" r=\"4\"/>","mic":"<rect x=\"9\" y=\"2\" width=\"6\" height=\"13\" rx=\"3\"/><path d=\"M5 10v2a7 7 0 0 0 14 0v-2m-7 9v3\"/>","water":"<path d=\"M12 3c-3 5-7 9-7 13a7 7 0 0 0 14 0c0-4-4-8-7-13Z\"/>","meals":"<path d=\"M4 3v7a3 3 0 0 0 6 0V3M7 3v19M18 3c-3 3-4 7-4 11h4m0-11v19\"/>","arrow":"<path d=\"M5 12h14m-6-6 6 6-6 6\"/>"};
const icon=(n)=>`<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||''}</svg>`;
const logo=()=>`<div class="row" style="justify-content:flex-start"><span class="logo">${icon('activity')}</span><span class="brand">MyBody<b>Track</b></span></div>`;
const label=(t,html)=>`<label>${t}${html}</label>`, input=(n,v,type='text',extra='')=>`<input name="${n}" type="${type}" value="${esc(v)}" ${extra}>`, select=(n,vals,v)=>`<select name="${n}">${vals.map(([a,b])=>`<option value="${esc(a)}" ${String(a)===String(v)?'selected':''}>${esc(b)}</option>`).join('')}</select>`, btn=(text,action,cls='secondary',extra='')=>`<button type="button" class="${cls}" data-act="${action}" ${extra}>${text}</button>`;
const navIcon=icon;
function render(){document.body.classList.toggle('light',s.prefs.theme==='light');document.querySelector('meta[name=theme-color]')?.setAttribute('content',s.prefs.theme==='light'?'#f3f4f6':'#000000');if(!demo&&!user){root.innerHTML=`<section class="login"><div class="logo">${icon('activity')}</div><div><p class="eyebrow">YOUR PERSONAL WELLNESS COMPANION</p><h1>MyBody<span style="color:var(--green)">Track</span></h1><p class="muted">Your Food. Your Body. Your Goals.</p></div><div class="card"><h2>Build better habits.</h2><p class="muted">Food, hydration, progress and mindset — in one place.</p>${btn('G &nbsp; Continue with Google','google','primary wide',C.firebase?'':'disabled')}${C.allowDemo?btn('Explore local demo','demo','secondary wide'):''}<p class="notice">${C.firebase?'Your Google password is never collected.':'Google login requires Firebase configuration. Demo data stays on this device.'} ${esc(initError)}</p></div><small>For adults 18+. Nutrition estimates are not medical advice.</small></section>`;return}if(!s.profile||!s.goal||step===3){root.innerHTML=`<main>${logo()}${onboarding()}</main>`;return}const p=s.profile;root.innerHTML=`<main class="page-${tab}"><header>${logo()}<div class="row">${demo?'<span class="demo">LOCAL DEMO</span>':''}${btn(icon(s.prefs.theme==='dark'?'sun':'moon'),'theme','chip theme-button','aria-label="Toggle theme"')}</div></header>${({home,food,history,mindset,profile,coach:coachView,planner:plannerView})[tab]()}</main><nav class="nav" aria-label="Main navigation">${[['home','⌂','Home'],['history','▦','History'],['food','✦','AI Food'],['mindset','◇','Mindset'],['profile','◎','Profile']].map(([id,icon,name])=>`<button class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''} data-act="tab" data-id="${id}"><span>${navIcon(id)}</span>${name}</button>`).join('')}</nav>`;}
function onboarding(){const p=s.profile||{name:user?.displayName||(demo?'Demo User':''),age:22,height:165,weight:45,sex:'male',activity:'1.2'};if(step===1||!s.profile)return `<div class="card"><p class="eyebrow">STEP 1 / 3</p><h1>About you</h1><p class="muted">Create your personal health profile.</p><form id="profileForm" class="stack" novalidate><p id="profileError" role="alert" aria-live="polite" style="color:var(--red);display:none"></p>${label('Name',input('name',p.name,'text','required maxlength="80"'))}<div class="grid2">${label('Height (cm)',input('height',p.height,'number','required min="100" max="250" step="0.1"'))}${label('Weight (kg)',input('weight',p.weight,'number','required min="25" max="350" step="0.1"'))}</div>${label('Age (years)',input('age',p.age,'number','required min="18" max="100"'))}${label('Sex (for calorie estimate)',select('sex',[['male','Male'],['female','Female'],['other','Other / prefer not to say']],p.sex))}${label('Activity level',select('activity',[['1.2','Mostly sitting'],['1.375','Lightly active'],['1.55','Moderately active'],['1.725','Very active']],p.activity))}<button type="submit" class="primary">Calculate BMI →</button></form><small>Adults only. BMI is a screening tool. Unintentional weight change should be discussed with a clinician.</small></div>`;const b=bmi(p.weight,p.height), suggested=b<18.5?Math.ceil(21*(p.height/100)**2):b>=25?Math.round(23*(p.height/100)**2):p.weight;if(step===2)return `<div class="card"><p class="eyebrow">STEP 2 / 3</p><h1>Your body analysis</h1><div class="hero card"><small>Current BMI</small><div class="big">${b.toFixed(2)}</div><strong>${cat(b)}</strong>${bar(b-10,30)}<small>Adult reference BMI range: 18.5–24.9</small></div><p>${b<18.5?'Consider gradual weight gain. If your weight has fallen unexpectedly, seek a medical check-up.':b>=25?'Consider weight management based on health and personal circumstances.':'Maintaining your weight is a reasonable option.'}</p><form id="goalForm" class="stack" novalidate><p id="goalError" role="alert" aria-live="polite" style="color:var(--red);display:none"></p>${label('Target weight (kg)',input('target',suggested,'number','required min="25" max="350" step="0.1"'))}${label('Weekly pace',select('pace',[['0.25','Gradual · 0.25 kg/week'],['0.5','Balanced · 0.5 kg/week'],['0.75','Fast · 0.75 kg/week']],'.5'.replace(/^\./,'0.')))}<small>Timeline and calorie needs are estimates. Seek medical guidance before rapid weight changes.</small><button type="submit" class="primary">Calculate my plan →</button></form>${btn('Back','backProfile')}</div>`;return `<div class="card"><p class="eyebrow">STEP 3 / 3</p><h1>Build your routine</h1>${mealEditor()}<p class="muted">You can adjust the number, names and deadlines of your meals anytime.</p>${btn('Open my dashboard →','finish','primary wide')}</div>`}
function mealEditor(){return `<div class="stack">${s.meals.map(m=>`<div class="row"><input aria-label="Meal name" value="${esc(m.name)}" data-meal-name="${m.id}" maxlength="40"><input aria-label="Deadline" type="time" value="${m.time}" data-meal-time="${m.id}" style="max-width:125px">${btn('×','removeMeal','chip',`data-id="${m.id}" aria-label="Remove meal"`)}</div>`).join('')}${btn('+ Add meal','addMeal','secondary wide')}</div>`}
function home(){const d=day(),g=s.goal,f=forecast(),t=total(d),w=water(d),done=s.meals.filter(m=>['done','late'].includes(status(m,d))).length, q=quoteSelection||Q[(Math.floor(new Date()/86400000))%Q.length];return `<div class="row"><div><p class="eyebrow">${new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'})}</p><h1>Hi, ${esc(s.profile.name.split(' ')[0])}.</h1></div><span class="tag">${g.dir>0?'WEIGHT GAIN':g.dir<0?'WEIGHT LOSS':'MAINTAIN'}</span></div>${v4Home()}<section class="card hero"><div class="row"><p class="eyebrow">YOUR TRANSFORMATION</p><span class="hero-mark">${icon('activity')}</span></div><div class="row"><div><small>Current</small><div class="big">${current().toFixed(1)} <small>kg</small></div></div><span class="journey-arrow">${icon('arrow')}</span><div class="target-weight" style="text-align:right"><small>Target</small><div class="big">${g.target.toFixed(1)} <small>kg</small></div></div></div>${bar(f.progress,100)}<div class="row"><small>${f.remaining.toFixed(1)} kg remaining</small><strong>${f.days===null?'Reassessing':f.days+' days est.'}</strong></div><small>${f.days===null?'Trend not yet moving toward goal. Review your routine.':f.rate===null?'Based on planned pace; update with weigh-ins.':'Based on logged weight trend, not a guarantee.'}</small>${btn('Log weight','weight','secondary wide')}</section><section class="card nutrition-card"><div class="section-title"><h2>Today's nutrition</h2><span class="tag">${fmt(Math.max(0,g.kcal-t.kcal))} kcal left</span></div><div class="nutrition-overview"><div class="rings" role="img" aria-label="Daily calorie, protein, carbs and fat progress"><svg viewBox="0 0 200 200">${[['kcal',86,'var(--green)'],['protein',69,'var(--blue)'],['carbs',52,'var(--carb)'],['fat',35,'var(--gold)']].map(([k,r,c])=>{const len=2*Math.PI*r,p=clamp(g[k]?t[k]/g[k]:0,0,1);return `<circle cx="100" cy="100" r="${r}" fill="none" stroke="${c}" opacity=".16" stroke-width="11"/><circle class="ring-progress" cx="100" cy="100" r="${r}" fill="none" stroke="${c}" stroke-width="11" stroke-linecap="round" stroke-dasharray="${p*len} ${len}" transform="rotate(-90 100 100)" ${p===0?'opacity="0"':''}/>`}).join('')}</svg><div class="ring-center"><strong>${fmt(t.kcal)}</strong><small>kcal</small></div></div><div class="nutrition-legend"><p class="eyebrow">DAILY GOAL</p><div class="stat">${fmt(g.kcal)} <small>kcal</small></div>${[['Calories','kcal','var(--green)'],['Protein','protein','var(--blue)'],['Carbs','carbs','var(--carb)'],['Fat','fat','var(--gold)']].map(([n,k,c])=>`<div class="row legend-row"><span><i style="background:${c}"></i>${n}</span><strong>${fmt(g[k]?t[k]/g[k]*100:0)}%</strong></div>`).join('')}</div></div></section><div class="grid3 macro-bento">${[['Protein','protein','var(--blue)'],['Carbs','carbs','var(--carb)'],['Fat','fat','var(--gold)']].map(([n,k,c])=>`<section class="card macro-tile" style="--metric:${c}"><small>${n}</small><div class="stat">${fmt(t[k])}<small> g</small></div><small>of ${g[k]} g</small>${bar(t[k],g[k],c)}</section>`).join('')}</div>${btn(icon('food')+' Log food with AI','tab','primary wide ai-cta','data-id="food"')}<div class="grid2 wellness-bento"><section class="card hydration-tile"><div class="tile-icon">${icon('water')}</div><p class="eyebrow">HYDRATION</p><div class="stat">${(w/1000).toFixed(2)} L</div><small>Goal ${(s.prefs.water/1000).toFixed(2)} L</small>${bar(w,s.prefs.water,'var(--blue)')}${btn('+ 250 ml','water','secondary wide','data-ml="250"')}</section><section class="card meals-tile"><div class="tile-icon">${icon('meals')}</div><p class="eyebrow">MEAL ROUTINE</p><div class="stat">${done}/${s.meals.length}</div><small>Completed today</small>${bar(done,s.meals.length)}${btn('View routine','meals','secondary wide')}</section></div><section class="card" id="routine"><div class="row"><h2>Daily meal checklist</h2>${btn('Edit','tab','chip','data-id="profile"')}</div>${mealRows(d,today())}</section><section class="card"><h2>Water log</h2><div class="grid3">${[150,250,500].map(n=>btn('+ '+n+' ml','water','secondary',`data-ml="${n}"`)).join('')}</div><div class="row">${btn('Custom amount','customWater')}${btn('Undo last','undoWater','chip',d.water.length?'':'disabled')}</div></section><section class="card"><h2>Today's check-in</h2><p class="muted">${feedback(d)}</p></section><section class="card"><p class="eyebrow">MINDSET · ${esc(q.category)}</p><button class="quote-btn" data-act="quote" data-id="${q.id}"><div class="quote">“${esc(q.text)}”</div><small>— ${esc(q.speaker)}</small></button><span class="tag">Tap for original source →</span></section>`}
function mealRows(d,k){return s.meals.map(m=>{const st=status(m,d,k),text={done:'Completed',late:'Completed late',missed:'Missed',pending:'Pending',overdue:'Overdue',unconfirmed:'Unconfirmed'}[st]||st;return `<div class="meal"><input type="checkbox" aria-label="Complete ${esc(m.name)}" data-meal-check="${m.id}" data-date="${k}" ${['done','late'].includes(st)?'checked':''}><div class="info"><strong>${esc(m.name)}</strong><br><small>Before ${clock(m.time)}</small><br><span class="status ${['done','late'].includes(st)?'done':st==='missed'?'missed':''}">${text}</span></div>${btn('Log','logMeal','chip',`data-id="${m.id}" data-date="${k}"`)}${btn(st==='missed'?'Undo':'Missed','missMeal','chip',`data-id="${m.id}" data-date="${k}"`)}</div>`}).join('')}
function feedback(d){const t=total(d),g=s.goal,diff=g.kcal-t.kcal, missed=Object.values(d.status).filter(x=>x.state==='missed').length;return `${missed?`${missed} meal(s) marked missed. `:''}${!d.food.length?'No intake logged yet; missing logs are not proof of skipped meals.':diff>0?`${fmt(diff)} kcal below today's target so far. ${g.dir>0?'Consistently low intake may slow weight gain.':'Keep regular meals; do not compensate by skipping food.'}`:`${fmt(Math.abs(diff))} kcal above target so far. Daily variation is normal.`} Goal estimates update with measured weight trends.`}
function food(){const d=day(selectedDate);return `<h1>AI food analysis</h1><p class="muted">Type, upload a photo or record a voice note in Hindi, Hinglish or English.</p><section class="card"><label>Meal date${input('foodDate',selectedDate,'date',`max="${today()}" id="foodDate"`)}</label>${label('Meal',`<select id="foodMeal">${s.meals.map(m=>`<option value="${m.id}" ${m.id===chosenMeal?'selected':''}>${esc(m.name)}</option>`).join('')}<option value="other" ${chosenMeal==='other'?'selected':''}>Other / snack</option></select>`)}<textarea id="foodText" placeholder="Aaj maine 2 roti, 1 katori dal aur 250 ml milk piya...">${esc(foodDraft)}</textarea><div class="grid2"><label class="secondary center">${icon('camera')} Photo<input id="imageFile" class="file" type="file" accept="image/jpeg,image/png,image/webp" capture="environment"></label><label class="secondary center">${icon('mic')} Audio file<input id="audioFile" class="file" type="file" accept="audio/*"></label></div><div class="row">${btn(recorder?.state==='recording'?'■ Stop recording':'🎙 Record voice','record','secondary')}${btn('Clear media','clearMedia','chip')}</div><small>${esc(fileDraft?.name||recorded?.name||'No attachment')} · max 5 MB. Add quantities and cooking oil for better estimates.</small>${aiNotice("food")}${btn(busy?'Analyzing…':'✦ Analyze with Gemini','analyze','primary wide',busy?'disabled':'')}${btn('Enter nutrition manually','manual','secondary wide')}<p class="notice">${demo?'Demo mode: live AI is unavailable until the backend is configured. Manual food logging works.':'AI estimates may be inaccurate. Review before saving.'}</p>${aiError?`<p class="alert">${esc(aiError)}</p>`:''}</section>${analysis?analysisView():''}${favoriteView()}<section class="card"><h2>Food diary · ${esc(selectedDate)}</h2>${d.food.length?d.food.map(f=>`<div class="meal"><div class="info"><strong>${esc(f.name)}</strong><br><small>${fmt(f.kcal)} kcal · P ${fmt(f.protein)}g · C ${fmt(f.carbs)}g · F ${fmt(f.fat)}g</small></div><div class="v4-food-actions">${btn('♡ Save','saveFavorite','chip',`data-id="${esc(f.id)}"`)}${btn('Remove','deleteFood','chip',`data-id="${esc(f.id)}"`)}</div></div>`).join(''):'<p class="empty">Nothing logged yet.</p>'}</section>`}
function analysisView(){return `<section class="card review-card"><p class="eyebrow">NUTRITION REVIEW</p><h2>Review nutrition estimate</h2>${analysis.question?`<p class="notice">${esc(analysis.question)} Add the answer to your input and analyze again.</p>`:''}<p class="muted">${esc(addressUser())}, ${esc(analysis.notes||'Portions aur values save karne se pehle check kar lo.')}</p>${breakdownView()}<form id="saveFoodForm" class="stack">${label('Food / meal',input('name',analysis.name||'Meal','text','required maxlength="180"'))}<div class="grid2">${[['kcal','Calories (kcal)'],['protein','Protein (g)'],['carbs','Carbs (g)'],['fat','Fat (g)'],['fiber','Fibre (g)'],['sugar','Sugar (g)'],['sodium','Sodium (mg)'],['calcium','Calcium (mg)'],['iron','Iron (mg)']].map(([k,l])=>label(l,input(k,analysis[k]??'','number',`${['kcal','protein','carbs','fat'].includes(k)?'required':''} min="0" max="50000" step="0.1"`))).join('')}</div><label class="inline-check"><input type="checkbox" name="complete" checked>Mark selected meal complete</label><button class="primary">Save food log</button></form></section>`}
function history(){const base=new Date();base.setMonth(base.getMonth()+monthOffset,1);const days=new Date(base.getFullYear(),base.getMonth()+1,0).getDate(), offset=(base.getDay()+6)%7,d=getDay(selectedDate),t=total(d),list=logs(),g=s.goal;let points=list.slice(-30);const lo=Math.min(g.initial,g.target,...points.map(p=>p.w))-1,hi=Math.max(g.initial,g.target,...points.map(p=>p.w))+1,xy=(w,i)=>[30+i*280/Math.max(1,points.length-1),148-(w-lo)/(hi-lo)*125];return `<h1>Progress & history</h1>${weeklyView()}<section class="card history-chart"><div class="row"><h2>Weight progress</h2>${btn('+ Weigh-in','weight','chip')}</div><div class="stat">${current().toFixed(1)} kg</div><svg class="chart" viewBox="0 0 340 175" role="img" aria-label="Logged weight trend"><path d="M30 20 V148 H315" stroke="currentColor" opacity=".3" fill="none"/><line x1="30" x2="315" y1="${xy(g.target,0)[1]}" y2="${xy(g.target,0)[1]}" stroke="#79b9ff" stroke-dasharray="4 4"/><text x="315" y="${xy(g.target,0)[1]-5}" text-anchor="end" fill="currentColor" font-size="10">Goal ${g.target}kg</text>${points.length?`<polyline fill="none" stroke="#65e6a5" stroke-width="3" points="${points.map((p,i)=>xy(p.w,i).join(',')).join(' ')}"/>${points.map((p,i)=>`<circle cx="${xy(p.w,i)[0]}" cy="${xy(p.w,i)[1]}" r="4" fill="#65e6a5"><title>${p.date}: ${p.w} kg</title></circle>`).join('')}`:'<text x="170" y="90" text-anchor="middle" fill="currentColor" font-size="12">Log weight to see your trend</text>'}</svg><small>Original plan: ${g.days===null?'not available':g.days+' days'} · current estimate: ${forecast().days??'not enough progress'}${forecast().days===null?'':' days'}</small></section><section class="card"><div class="row">${btn('‹','prevMonth','chip')}<strong>${base.toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</strong>${btn('›','nextMonth','chip')}</div><div class="calendar">${['M','T','W','T','F','S','S'].map(x=>`<small class="center">${x}</small>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:days},(_,i)=>{let dt=dateKey(new Date(base.getFullYear(),base.getMonth(),i+1));return `<button data-act="date" data-id="${dt}" class="${dt===selectedDate?'selected ':''}${s.days[dt]?'marked':''}" ${dt>today()?'disabled':''}>${i+1}</button>`}).join('')}</div></section><section class="card"><h2>${selectedDate}</h2><div class="grid3"><div><small>Calories</small><div class="stat">${fmt(t.kcal)}</div></div><div><small>Protein</small><div class="stat">${fmt(t.protein)}g</div></div><div><small>Water</small><div class="stat">${(water(d)/1000).toFixed(1)}L</div></div></div>${mealRows(d,selectedDate)}<p class="muted">${feedback(d)}</p></section><section class="card"><h2>Last 7 days</h2>${Array.from({length:7},(_,i)=>shift(-i)).map(k=>{const x=getDay(k);return `<div class="row"><small>${k}</small><span>${fmt(total(x).kcal)} kcal</span><span>${x.weight??'—'} kg</span></div>`}).join('')}</section>`}
function mindset(){const q=Q.find(x=>x.id===quoteId);if(q)return `<div class="row">${btn('‹ All quotes','closeQuote','chip')}<span class="tag">SOURCE DETAILS</span></div><section class="card hero"><p class="eyebrow">${esc(q.category)}</p><div class="quote">“${esc(q.text)}”</div><strong>— ${esc(q.speaker)}</strong><small>${esc(q.work)}</small></section><section class="card"><h2>Original attribution</h2><p><strong>Speaker:</strong> ${esc(q.speaker)}</p>${q.actor?`<p><strong>Actor:</strong> ${esc(q.actor)}</p>`:''}<p><strong>Source:</strong> ${esc(q.work)}</p><a target="_blank" rel="noopener noreferrer" href="${esc(q.source)}">Open reference ↗</a><div class="line"></div><h2>Meaning (Hinglish)</h2><p>${esc(q.meaning)}</p><h2>Context</h2><p class="muted">${esc(q.context)}</p><div class="grid2">${btn(s.favorites.includes(q.id)?'★ Saved':'☆ Save','favorite','secondary',`data-id="${q.id}"`)}${btn('Share quote','share','secondary',`data-id="${q.id}"`)}</div></section>`;return `<h1>Mindset</h1><p class="muted">Body · Mind · Money · Power · Discipline</p><section class="card mindset-intro"><p class="eyebrow">DAILY INSPIRATION</p><h2>Daily mindset</h2><p class="muted">Original sourced excerpts, never AI-invented attributions. AI may rank the approved collection against preferences and current trends.</p>${btn(busy?'Selecting…':'✦ Select a quote with AI','pickQuote','primary wide',busy?'disabled':'')}${quoteSelection?`<button class="quote-btn" data-act="quote" data-id="${quoteSelection.id}"><div class="quote">“${esc(quoteSelection.text)}”</div><small>${esc(quoteSelection.speaker)}</small></button>`:''}<small>Starter library is limited; more licensed/verified entries can be added.</small></section><section class="card">${label('Filter',`<select id="qFilter">${['All','Favorites',...new Set(Q.map(x=>x.category))].map(x=>`<option ${x===qFilter?'selected':''}>${esc(x)}</option>`).join('')}</select>`)}${Q.filter(x=>qFilter==='All'||(qFilter==='Favorites'?s.favorites.includes(x.id):x.category===qFilter)).map(q=>`<button class="quote-btn" data-act="quote" data-id="${q.id}"><p class="eyebrow">${esc(q.category)}</p><div class="quote" style="font-size:20px">“${esc(q.text)}”</div><small>${esc(q.speaker)} · ${esc(q.work)}</small></button><div class="line"></div>`).join('')||'<p class="empty">No quotes in this category yet.</p>'}</section>`}
const settingsOpen=new Set();
root.addEventListener('toggle',e=>{if(e.target.matches?.('details[data-setting]')){if(e.target.open)settingsOpen.add(e.target.dataset.setting);else settingsOpen.delete(e.target.dataset.setting)}},true);
const setting=(id,title,body)=>`<details class="card settings-card" data-setting="${id}" ${settingsOpen.has(id)?'open':''}><summary><span>${title}</span><span class="settings-chevron" aria-hidden="true">›</span></summary><div class="settings-body">${body}</div></details>`;
function profile(){const p=s.profile,g=s.goal,r=s.prefs;return `<h1>Your profile</h1><section class="card profile-overview"><div class="row"><div class="profile-identity"><div class="avatar">${icon('profile')}</div><h2>${esc(p.name)}</h2><small>${esc(user?.email||'Local demo profile')}</small></div><div class="stat">${bmi(current(),p.height).toFixed(1)}<br><small>BMI</small></div></div><div class="grid2 profile-metrics"><div><small>Current weight</small><div class="stat">${current().toFixed(1)} kg</div></div><div><small>Height</small><div class="stat">${p.height} cm</div></div><div><small>Age</small><div class="stat">${p.age}</div></div><div><small>BMR estimate</small><div class="stat">${g.bmr} <small>kcal</small></div></div><div><small>TDEE estimate</small><div class="stat">${g.tdee} <small>kcal</small></div></div></div>${btn('Edit body profile / goal','editProfile','secondary wide')}</section><details class="card settings-card" data-setting="nutrition" ${settingsOpen.has('nutrition')?'open':''}><summary><span>Daily nutrition goals</span><span class="settings-chevron" aria-hidden="true">›</span></summary><div class="settings-body"><form id="goalsEdit" class="stack"><div class="grid2">${[['kcal','Calories'],['protein','Protein (g)'],['carbs','Carbs (g)'],['fat','Fat (g)']].map(([k,l])=>label(l,input(k,g[k],'number',`required min="${k==='kcal'?1200:0}" max="${k==='kcal'?5000:1000}"`))).join('')}</div><button class="secondary">Save nutrition targets</button></form><small>Individual requirements differ; seek guidance for underweight or medical conditions.</small></div></details><details class="card settings-card" data-setting="meals" ${settingsOpen.has('meals')?'open':''}><summary><span>Meal deadlines</span><span class="settings-chevron" aria-hidden="true">›</span></summary><div class="settings-body">${mealEditor()}</div></details><details class="card settings-card" data-setting="notifications" ${settingsOpen.has('notifications')?'open':''}><summary><span>Notifications & hydration</span><span class="settings-chevron" aria-hidden="true">›</span></summary><div class="settings-body"><form id="prefsForm" class="stack">${label('Daily water goal (ml)',input('water',r.water,'number','required min="500" max="5000" step="50"'))}${[['mealAlerts','Meal reminders'],['waterAlerts','Water reminders'],['quoteAlerts','Mindset quotes'],['weeklyAlerts','Weekly report reminder (Monday)']].map(([k,l])=>`<label class="inline-check"><input name="${k}" type="checkbox" ${r[k]?'checked':''}>${l}</label>`).join('')}<div class="grid2">${label('Before deadline',select('mealBefore',[[15,'15 min'],[30,'30 min'],[60,'60 min']],r.mealBefore))}${label('Repeat meal reminder',select('repeat',[[15,'15 min'],[30,'30 min'],[60,'60 min']],r.repeat))}${label('Water reminder',select('waterRepeat',[[30,'30 min'],[60,'1 hour'],[120,'2 hours']],r.waterRepeat))}${label('Quote times (24h)',input('quoteTimes',r.quoteTimes,'text','placeholder="08:00,18:00"'))}${label('Active from',input('start',r.start,'time','required'))}${label('Quiet hours start',input('end',r.end,'time','required'))}</div><p class="eyebrow">QUOTE INTERESTS</p>${defaults().prefs.categories.map(x=>`<label class="inline-check"><input name="category" value="${esc(x)}" type="checkbox" ${r.categories.includes(x)?'checked':''}>${esc(x)}</label>`).join('')}<button class="primary">Save settings</button></form>${btn('Enable phone notifications','enablePush','secondary wide')}<small>Background push requires deployed HTTPS, permission, backend setup and connectivity. On iPhone, install to Home Screen first.</small></div></details><details class="card settings-card" data-setting="account" ${settingsOpen.has('account')?'open':''}><summary><span>Account & privacy</span><span class="settings-chevron" aria-hidden="true">›</span></summary><div class="settings-body">${btn('Install app','install','secondary wide')}${btn('Export my data (JSON)','export','secondary wide')}${privacyView()}${btn('Sign out','logout','secondary wide')}${btn('Delete account and data','deleteAccount','danger wide')}<small>Personal wellness app for adults. AI estimates are not medical advice. Google free-tier AI data use may differ from paid plans. Food analysis sends only your input. Your name stays in the app. Profile sharing with Gemini is optional and requires the configured paid service plus permission.</small></div></details>`}
let installEvent=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e});
const redraw=()=>{persist();render()};const api=async(path,data)=>{if(!user||!C.apiBase)throw Error('Live backend is not configured.');const r=await fetch(C.apiBase.replace(/\/$/,'')+path,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+await user.getIdToken()},body:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j};
function formData(form){return Object.fromEntries(new FormData(form))}root.addEventListener('submit',e=>{e.preventDefault();const form=e.target,v=formData(form);if(form.id==='profileForm'){const fail=(field,message)=>{const err=$('#profileError');err.textContent=message;err.style.display='block';form.elements[field].focus();toast(message)};if(!v.name.trim())return fail('name','Please enter your name.');if(!v.height||!Number.isFinite(Number(v.height))||Number(v.height)<100||Number(v.height)>250)return fail('height','Enter height between 100 and 250 cm.');if(!v.weight||!Number.isFinite(Number(v.weight))||Number(v.weight)<25||Number(v.weight)>350)return fail('weight','Enter weight between 25 and 350 kg.');if(!v.age||!Number.isInteger(Number(v.age))||Number(v.age)<18||Number(v.age)>100)return fail('age','Enter a whole-number age between 18 and 100.');s.profile={name:v.name.trim(),height:num(v.height),weight:num(v.weight),age:num(v.age),sex:v.sex,activity:v.activity};s.goal=null;step=2;redraw();window.scrollTo(0,0)}else if(form.id==='goalForm'){const target=num(v.target),p=s.profile,pace=num(v.pace);const fail=message=>{const err=$('#goalError');err.textContent=message;err.style.display='block';form.elements.target.focus();toast(message)};if(!v.target||target<25||target>350)return fail('Enter a target weight between 25 and 350 kg.');if(!Number.isFinite(pace)||![0.25,0.5,0.75].includes(pace))return fail('Choose a valid weekly pace.');if(bmi(target,p.height)<18.5&&target<p.weight)return fail('A weight-loss goal below healthy BMI is not supported.');if(bmi(p.weight,p.height)<18.5&&target<p.weight)return fail('Seek medical guidance before weight loss.');s.goal=plan(p,target,pace);step=3;day().weight=p.weight;redraw();window.scrollTo(0,0)}else if(form.id==='saveFoodForm'){const f={id:rid(),name:v.name.trim(),meal:chosenMeal||s.meals[0]?.id||'other',at:new Date().toISOString()};for(const k of ['kcal','protein','carbs','fat','fiber','sugar','sodium','calcium','iron'])f[k]=v[k]===''?null:num(v[k]);if(analysis?.items?.length){f.items=analysis.items;f.estimateEdited=['kcal','protein','carbs','fat','fiber','sugar','sodium','calcium','iron'].some(k=>f[k]!==analysis[k])}if(!f.name)return toast('Enter a food name.');const d=day(selectedDate);d.food.push(f);if(v.complete&&s.meals.some(m=>m.id===f.meal)){const m=s.meals.find(m=>m.id===f.meal);d.status[f.meal]={state:selectedDate===today()&&timeMin()>mins(m.time)?'late':'done',at:new Date().toISOString()}}analysis=null;foodDraft='';fileDraft=null;recorded=null;aiError='';redraw();toast('Meal saved.')}else if(form.id==='prefsForm'){if(mins(v.end)<=mins(v.start))return toast('End time must be after start time.');const ts=v.quoteTimes.split(',').map(x=>x.trim()).filter(x=>/^([01]\d|2[0-3]):[0-5]\d$/.test(x));if(v.quoteAlerts&&!ts.length)return toast('Enter a valid 24-hour quote time.');s.prefs={...s.prefs,water:num(v.water),mealAlerts:!!v.mealAlerts,waterAlerts:!!v.waterAlerts,quoteAlerts:!!v.quoteAlerts,weeklyAlerts:!!v.weeklyAlerts,mealBefore:num(v.mealBefore),repeat:num(v.repeat),waterRepeat:num(v.waterRepeat),start:v.start,end:v.end,quoteTimes:ts.slice(0,8).join(','),categories:new FormData(form).getAll('category')};redraw();toast('Settings saved.')}else if(form.id==='goalsEdit'){for(const k of ['kcal','protein','carbs','fat'])s.goal[k]=num(v[k]);redraw();toast('Targets saved.')}});
root.addEventListener('input',e=>{if(e.target.id==='foodText')foodDraft=e.target.value;if(e.target.dataset.mealName){let m=s.meals.find(m=>m.id===e.target.dataset.mealName);if(m){m.name=e.target.value;persist()}}});
root.addEventListener('change',e=>{const el=e.target;if(el.dataset.mealTime){s.meals.find(m=>m.id===el.dataset.mealTime).time=el.value;persist()}if(el.dataset.mealCheck){const m=s.meals.find(m=>m.id===el.dataset.mealCheck),d=day(el.dataset.date);if(el.checked)d.status[m.id]={state:el.dataset.date===today()&&timeMin()>mins(m.time)?'late':'done',at:new Date().toISOString()};else delete d.status[m.id];redraw()}if(el.id==='foodDate'){selectedDate=el.value||today();render()}if(el.id==='foodMeal')chosenMeal=el.value;if(el.id==='qFilter'){qFilter=el.value;render()}if(['imageFile','audioFile'].includes(el.id)){const f=el.files[0];if(f&&f.size>5*1024*1024)return toast('File exceeds 5 MB.');fileDraft=f||null;recorded=null;render()}});
root.addEventListener('click',async e=>{const el=e.target.closest('[data-act]');if(!el||el.disabled)return;const a=el.dataset.act,id=el.dataset.id,k=el.dataset.date||today();try{switch(a){case 'coachOpen':tab='coach';render();window.scrollTo(0,0);break;case 'plannerOpen':tab='planner';render();window.scrollTo(0,0);break;case 'weeklyOpen':tab='history';render();window.scrollTo(0,0);break;case 'coachAsk':await runWellness('coach');break;case 'plannerAsk':await runWellness('planner');break;case 'saveFavorite':saveFavorite(id);break;case 'useFavorite':useFavorite(id);break;case 'quickFavorite':quickFavorite(id);break;case 'removeFavorite':if(confirm('Remove this saved meal?')){s.favoriteFoods=(s.favoriteFoods||[]).filter(x=>x.id!==id);redraw()}break;case 'exportCSV':exportCSV();break;case 'exportBackend':{const owner=user?.uid;const data=await api('/privacy/export',{});if(user?.uid===owner)downloadData('MyBodyTrack-backend.json',JSON.stringify(data,null,2),'application/json');break;}case 'privacySave':await savePrivacy();break;case 'aiPermissionReset':clearAIPermission();render();toast('AI permissions reset on this device.');break;case 'aiProfileToggle':toggleAIProfile();render();break;case 'demo':demo=true;s=defaults();readLocal();step=s.profile&&!s.goal?2:1;render();break;case 'google':if(!firebase)throw Error(initError||'Firebase is loading.');await firebase.authSDK.signInWithPopup(firebase.auth,new firebase.authSDK.GoogleAuthProvider());break;case 'tab':tab=id;quoteId=null;if(id==='food')selectedDate=today();render();window.scrollTo(0,0);break;case 'theme':s.prefs.theme=s.prefs.theme==='dark'?'light':'dark';redraw();break;case 'backProfile':step=1;render();break;case 'finish':if(s.meals.some(m=>!m.name.trim()))return toast('Name all meals.');step=4;redraw();break;case 'editProfile':if(confirm('Recalculate goal using a new profile? Existing logs remain.')){s.profile.weight=current();s.goal=null;step=1;redraw()}break;case 'addMeal':if(s.meals.length>=12)return toast('Maximum 12 meals.');s.meals.push({id:rid(),name:'New meal',time:'18:00'});redraw();break;case 'removeMeal':if(s.meals.length<=1)return toast('Keep at least one meal.');s.meals=s.meals.filter(m=>m.id!==id);redraw();break;case 'meals':$('#routine')?.scrollIntoView({behavior:'smooth'});break;case 'weight':{let v=prompt('Current weight (kg)',String(current()));if(v===null)break;let w=num(v);if(w<25||w>350)return toast('Enter a valid weight.');day().weight=Math.round(w*10)/10;redraw();toast('Weight recorded.');break}case 'water':day().water.push({ml:num(el.dataset.ml),at:new Date().toISOString()});redraw();break;case 'customWater':{let v=prompt('Water amount in ml','250');if(v!==null&&num(v)>0&&num(v)<=2000){day().water.push({ml:num(v),at:new Date().toISOString()});redraw()}break}case 'undoWater':day().water.pop();redraw();break;case 'missMeal':{let d=day(k);if(d.status[id]?.state==='missed')delete d.status[id];else if(confirm('Mark this meal as missed? You can undo it.'))d.status[id]={state:'missed',at:new Date().toISOString()};redraw();break}case 'logMeal':chosenMeal=id;selectedDate=k;tab='food';render();window.scrollTo(0,0);break;case 'manual':analysis={name:foodDraft||'',notes:'Manual entry — use a food label or other reliable nutrition reference.'};render();break;case 'clearMedia':fileDraft=null;recorded=null;render();break;case 'record':if(recorder?.state==='recording'){recorder.stop();break}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Voice recording is unavailable here. Upload an audio file instead.');stream=await navigator.mediaDevices.getUserMedia({audio:true});recorder=new MediaRecorder(stream);let chunks=[];recorder.ondataavailable=x=>chunks.push(x.data);recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());let b=new Blob(chunks,{type:recorder.mimeType});recorded=new File([b],'voice-note.'+(b.type.includes('mp4')?'m4a':'webm'),{type:b.type});fileDraft=null;render()};recorder.start();setTimeout(()=>{if(recorder?.state==='recording')recorder.stop()},60000);render();break;case 'analyze':if(!foodDraft.trim()&&!fileDraft&&!recorded)return toast('Describe a meal or add media.');if(demo)throw Error('Connect Gemini backend for live AI. Manual logging is available in this demo.');if(!allowAI())break;busy=true;aiError='';const epoch=wellnessEpoch;render();try{const f=fileDraft||recorded;let media=null;if(f){if(f.size>5*1024*1024)throw Error('Media exceeds 5 MB.');media={mime:f.type.split(';')[0],data:await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result.split(',')[1]);r.onerror=rej;r.readAsDataURL(f)})}}if(epoch!==wellnessEpoch)break;const result=await api('/analyze',{text:foodDraft,media});if(epoch===wellnessEpoch)analysis=result;}catch(err){if(epoch===wellnessEpoch)aiError=err.message}finally{if(epoch===wellnessEpoch){busy=false;render()}}break;case 'deleteFood':if(confirm('Delete this food entry?')){day(selectedDate).food=day(selectedDate).food.filter(f=>f.id!==id);redraw()}break;case 'prevMonth':monthOffset--;render();break;case 'nextMonth':if(monthOffset<0)monthOffset++;render();break;case 'date':selectedDate=id;render();break;case 'quote':quoteId=id;tab='mindset';render();window.scrollTo(0,0);break;case 'closeQuote':quoteId=null;render();break;case 'favorite':s.favorites=s.favorites.includes(id)?s.favorites.filter(x=>x!==id):[...s.favorites,id];redraw();break;case 'share':{let q=Q.find(x=>x.id===id),text=`“${q.text}” — ${q.speaker}, ${q.work}\n${q.source}`;if(navigator.share)await navigator.share({text});else if(navigator.clipboard){await navigator.clipboard.writeText(text);toast('Copied quote.')}else prompt('Copy quote',text);break}case 'pickQuote':{const options=Q.filter(q=>!s.quoteSeen.includes(q.id));if(!options.length)return toast('All starter quotes have been seen. New verified entries are needed.');let matches=options.filter(q=>s.prefs.categories.includes(q.category));if(!matches.length)matches=options;busy=true;render();try{let pick=demo?matches[0].id:(await api('/quote',{categories:s.prefs.categories,seen:s.quoteSeen})).id;quoteSelection=Q.find(q=>q.id===pick);if(!quoteSelection)throw Error('No new verified quote available.');s.quoteSeen.push(pick);persist()}finally{busy=false;render()}break}case 'enablePush':await enablePush();break;case 'install':if(installEvent){await installEvent.prompt();installEvent=null}else toast('Open browser menu → Add to Home Screen / Install app.');break;case 'export':{const blob=new Blob([JSON.stringify(s,null,2)],{type:'application/json'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='MyBodyTrack-backup.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);break}case 'logout':resetWellness();if(demo){demo=false;s=defaults();render()}else{clearTimeout(syncTimer);clearTimeout(pushTimer);await saveCloud();await unregisterPush();await firebase.authSDK.signOut(firebase.auth)}break;case 'deleteAccount':if(!confirm('Permanently delete your MyBodyTrack data?'))break;if(demo){localStorage.removeItem(storageKey());s=defaults();demo=false;render()}else{await firebase.authSDK.reauthenticateWithPopup(user,new firebase.authSDK.GoogleAuthProvider());clearTimeout(syncTimer);clearTimeout(pushTimer);await unregisterPush(true);await firebase.dbSDK.deleteDoc(firebase.dbSDK.doc(firebase.db,'users',user.uid));await firebase.authSDK.deleteUser(user);localStorage.removeItem(storageKey());s=defaults();render()}break;}}catch(err){toast(err.message||'Something went wrong.');if(busy){busy=false;render()}}});
async function saveCloud(){if(!firebase||!user)return;try{const data=JSON.parse(JSON.stringify(s));await firebase.dbSDK.setDoc(firebase.dbSDK.doc(firebase.db,'users',user.uid),{data,updatedAt:firebase.dbSDK.serverTimestamp()});}catch(e){toast('Cloud save failed: '+e.message)}}
async function initFirebase(){if(!C.firebase)return;try{const version='11.10.0',base=`https://www.gstatic.com/firebasejs/${version}/`,[appSDK,authSDK,dbSDK]=await Promise.all([import(base+'firebase-app.js'),import(base+'firebase-auth.js'),import(base+'firebase-firestore.js')]);const app=appSDK.initializeApp(C.firebase),auth=authSDK.getAuth(app),db=dbSDK.getFirestore(app);firebase={authSDK,dbSDK,auth,db};authSDK.onAuthStateChanged(auth,async u=>{user=u;resetWellness();if(!u){if(!demo)s=defaults();render();return}demo=false;s=defaults();readLocal();try{const snap=await dbSDK.getDoc(dbSDK.doc(db,'users',u.uid));if(snap.exists())s={...defaults(),...snap.data().data,prefs:{...defaults().prefs,...snap.data().data.prefs}}}catch(e){toast('Cloud load unavailable; using local cache.')}step=s.profile&&!s.goal?2:1;tab='home';render();deepLink();void reportActivity();void loadV4Status();await syncPush()})}catch(e){initError='Firebase initialization failed: '+e.message;render()}}
let activityDay='',activityInFlight=false;async function reportActivity(){if(!user||!C.apiBase||activityInFlight||s.prefs.activityOptout)return;const key=user.uid+':'+new Date().toISOString().slice(0,10);if(activityDay===key)return;activityInFlight=true;try{await api('/activity',{});activityDay=key}catch{}finally{activityInFlight=false}}
let swReg=null;async function getSW(){if(swReg)return swReg;if(!('serviceWorker'in navigator)||location.protocol==='file:')throw Error('Install from an HTTPS website to enable notifications.');swReg=await navigator.serviceWorker.register('./sw.js');return navigator.serviceWorker.ready}
function base64Bytes(s){return Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-s.length%4)%4)),c=>c.charCodeAt(0))}
async function enablePush(){if(demo||!user||!C.apiBase)throw Error('Live login and notification backend are required.');if(!('Notification'in window)||!('PushManager'in window))throw Error('Push is unavailable. On iPhone, add app to Home Screen first.');if(await Notification.requestPermission()!=='granted')throw Error('Notification permission was not granted.');let reg=await getSW(),sub=await reg.pushManager.getSubscription();if(!sub){let {key}=await api('/push-key',{});sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:base64Bytes(key)})}await syncPush();toast('Phone notifications enabled. Save reminder preferences in Profile.')}
async function syncPush(){if(!user||!C.apiBase||!('serviceWorker'in navigator)||!('PushManager'in window))return;try{let reg=await getSW(),sub=await reg.pushManager.getSubscription();if(!sub)return;await api('/schedule',{subscription:sub.toJSON(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,meals:s.meals,prefs:s.prefs,date:today(),status:day().status,water:water(day()),seen:s.quoteSeen})}catch(e){console.warn('Reminder sync:',e.message)}}
async function unregisterPush(all=false){if(!C.apiBase||!user)return;try{let sub=null;try{sub=await(await getSW()).pushManager.getSubscription()}catch{}await api('/unsubscribe',{endpoint:sub?.endpoint||'',all});if(sub)await sub.unsubscribe()}catch(e){if(all)throw e;console.warn(e)}}
let previousDate=today();setInterval(()=>{if(today()!==previousDate){previousDate=today();if(tab==='home'||tab==='history')render();syncPush()}},60000);window.addEventListener('online',()=>{if(user){syncPush();reportActivity()}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)reportActivity()});setInterval(()=>{if(!document.hidden)reportActivity()},60000);
// Notification deep links open the relevant view. User confirms meal completion inside the app.
function deepLink(){const q=new URLSearchParams(location.search);if(q.has('quote')&&Q.some(x=>x.id===q.get('quote'))){quoteId=q.get('quote');tab='mindset';render()}else if(q.has('meal')){tab='home';render();setTimeout(()=>$('#routine')?.scrollIntoView(),150)}else if(q.has('report')){tab='history';render()}else if(q.has('water')){tab='home';render()}}
// V4: separate saved foods from existing quote favourites. No automatic AI calls.
const foodKeys=['kcal','protein','carbs','fat','fiber','sugar','sodium','calcium','iron'];
let wellnessResult={},wellnessDraft={},wellnessBusy=false,wellnessEpoch=0,v4Status={};
function resetWellness(){wellnessEpoch++;wellnessResult={};wellnessDraft={};wellnessBusy=false;busy=false;v4Status={};analysis=null;foodDraft='';fileDraft=null;recorded=null;aiError='';}
async function loadV4Status(){const owner=user?.uid;try{const v=await api('/v4/status',{});if(user?.uid===owner){v4Status=v;if(tab==='home')render()}}catch{}}
function v4Home(){return `${v4Status.announcement?`<section class="card"><p class="eyebrow">APP ANNOUNCEMENT</p><p>${esc(v4Status.announcement)}</p></section>`:''}<section class="card v4-tools"><p class="eyebrow">YOUR WELLNESS TOOLS</p><div class="grid2">${btn('✦ AI Coach','coachOpen','secondary wide')}${btn('₹ Diet planner','plannerOpen','secondary wide')}</div>${btn('Weekly progress report →','weeklyOpen','chip wide')}</section>`}
function breakdownView(){if(!analysis?.items?.length)return '';return `<div class="v4-breakdown"><p class="eyebrow">ITEM-WISE ESTIMATES</p>${analysis.items.map(i=>`<div class="v4-item"><strong>${esc(i.name)}</strong><small>${esc(i.portion)} · ${i.kcal??'Unknown'} kcal · P ${i.protein??'—'}g · C ${i.carbs??'—'}g · F ${i.fat??'—'}g</small></div>`).join('')}<small>Totals are calculated by the server from individual items. Unknown nutrients stay blank. You can correct the totals below; portions and values are estimates.</small></div>`}
function favoriteView(){const a=s.favoriteFoods||[];return `<section class="card"><p class="eyebrow">NO AI REQUEST NEEDED</p><h2>Favourite foods & meals</h2>${a.length?a.map(f=>`<div class="meal"><div class="info"><strong>${esc(f.name)}</strong><br><small>${fmt(f.kcal)} kcal · P ${fmt(f.protein)}g · same portion</small></div><div class="v4-food-actions">${btn('+ Log','quickFavorite','chip',`data-id="${esc(f.id)}"`)}${btn('Review','useFavorite','chip',`data-id="${esc(f.id)}"`)}${btn('Remove','removeFavorite','chip',`data-id="${esc(f.id)}"`)}</div></div>`).join(''):'<p class="muted">Save a food from your diary to reuse it with one tap.</p>'}</section>`}
function saveFavorite(id){const f=getDay(selectedDate).food.find(x=>x.id===id);if(!f)return;const a=s.favoriteFoods||(s.favoriteFoods=[]);if(a.length>=60)return toast('Maximum 60 saved meals.');if(a.some(x=>x.name===f.name&&foodKeys.every(k=>x[k]===f[k])))return toast('Already saved.');a.push({id:rid(),name:f.name,...Object.fromEntries(foodKeys.map(k=>[k,f[k]??null]))});redraw();toast('Favourite saved.')}
function quickFavorite(id){const f=(s.favoriteFoods||[]).find(x=>x.id===id);if(!f)return;day(selectedDate).food.push({...f,id:rid(),meal:chosenMeal||s.meals[0]?.id||'other',at:new Date().toISOString()});redraw();toast('Saved portion logged. Confirm meal separately if needed.')}
function useFavorite(id){const f=(s.favoriteFoods||[]).find(x=>x.id===id);if(!f)return;analysis={...f,notes:'Saved portion — review or change quantities before logging.'};render();$('#saveFoodForm')?.scrollIntoView({behavior:'smooth'})}
function weekReport(){const now=new Date(),monday=new Date(now);monday.setDate(now.getDate()-((now.getDay()+6)%7));const keys=Array.from({length:7},(_,i)=>shift(i-7,monday));const rows=keys.map(date=>{const d=getDay(date);return {date,d,t:total(d),water:water(d),done:Object.values(d.status).filter(x=>['done','late'].includes(x.state)).length}});const logged=rows.filter(x=>x.d.food.length),hydrated=rows.filter(x=>x.d.water.length),weights=rows.filter(x=>x.d.weight!=null);const avg=(a,k)=>a.length?a.reduce((n,x)=>n+(k==='water'?x.water:x.t[k]),0)/a.length:null;return {rows,logged:logged.length,hydrated:hydrated.length,avgKcal:avg(logged,'kcal'),avgProtein:avg(logged,'protein'),avgWater:avg(hydrated,'water'),done:rows.reduce((n,x)=>n+x.done,0),weightChange:weights.length>=2?weights.at(-1).d.weight-weights[0].d.weight:null}}
function weeklyView(){const w=weekReport(),f=(v,suffix='')=>v===null?'—':fmt(v)+suffix;return `<section class="card"><p class="eyebrow">AUTOMATIC WEEKLY REPORT</p><h2>Last completed week</h2><small>${w.rows[0].date} — ${w.rows.at(-1).date}</small><div class="grid2 v4-report-grid"><div><small>Average calories</small><div class="stat">${f(w.avgKcal,' kcal')}</div></div><div><small>Average protein</small><div class="stat">${f(w.avgProtein,' g')}</div></div><div><small>Water / logged day</small><div class="stat">${w.avgWater===null?'—':(w.avgWater/1000).toFixed(2)+' L'}</div></div><div><small>Weight change</small><div class="stat">${w.weightChange===null?'—':(w.weightChange>0?'+':'')+w.weightChange.toFixed(1)+' kg'}</div></div></div><p class="muted">Food logged on ${w.logged}/7 days · Water logged on ${w.hydrated}/7 days · ${w.done} meal confirmations.</p>${w.rows.map(x=>`<div class="row"><small>${esc(x.date.slice(5))}</small><div class="v4-report-bar">${bar(x.t.kcal,s.goal.kcal)}</div><small>${x.d.food.length?fmt(x.t.kcal)+' kcal':'No log'}</small></div>`).join('')}<small>Missing records are excluded from averages, not treated as zero intake. Weight change needs at least two weigh-ins. A new report appears each Monday; enable the optional weekly notification in Profile.</small></section>`}
function wellnessContext(){const t=total(getDay(today())),g=s.goal,w=weekReport();return {sex:s.profile.sex,age:s.profile.age,height:s.profile.height,weight:current(),targetWeight:g.target,bmi:bmi(current(),s.profile.height),kcal:g.kcal,protein:g.protein,carbs:g.carbs,fat:g.fat,loggedKcal:t.kcal,loggedProtein:t.protein,loggedCarbs:t.carbs,loggedFat:t.fat,loggedDays:w.logged,...(w.avgKcal===null?{}:{averageKcal:w.avgKcal})}}
const aiPermissionKey=()=>`mbt-ai-permission-v41-${demo?'demo':user?.uid||'guest'}`;
function aiPermission(){try{return JSON.parse(localStorage.getItem(aiPermissionKey()))||{}}catch{return {}}}
function storeAIPermission(v){try{localStorage.setItem(aiPermissionKey(),JSON.stringify(v));return true}catch{return false}}
function clearAIPermission(){try{localStorage.removeItem(aiPermissionKey())}catch{}}
function allowAI(){const p=aiPermission();if(p.input===true)return true;const ok=confirm('AI privacy: Your submitted text, food photo or audio is sent to Google Gemini. Do not include names, faces, identifying, sensitive or confidential information in free-tier inputs. Free-tier inputs and responses may be used to improve Google services. Continue and remember this choice on this device? You can reset it in Profile.');if(ok)storeAIPermission({...p,input:true});return ok}
function profileSharing(){return v4Status.privateContext===true&&aiPermission().profile===true}
function toggleAIProfile(){if(!v4Status.privateContext)return;const p=aiPermission();if(p.profile){storeAIPermission({...p,profile:false});return}if(confirm('Allow the configured paid Gemini service to receive your age, sex, current weight, height, BMI, targets and nutrition summary for Coach and Diet Planner? Name and email are not sent automatically. Google may retain data temporarily for safety. You can turn this off in Profile.')){if(!storeAIPermission({...p,profile:true}))toast('Permission could not be saved.')}}
function aiNotice(mode){return `<small>AI input Google Gemini ko bheja jayega. Free tier par personal ya sensitive details, faces aur confidential information mat bhejo. ${mode==='food'?'Food estimates review karke save karo.':'AI suggestions general wellness ke liye hain.'} Permission Profile mein reset kar sakte ho.</small>`}
function addressUser(){const p=s.profile||{};return String(p.name||'').trim().split(/\s+/)[0].slice(0,40)|| (p.sex==='male'?'Bhai':p.sex==='female'?'Behen':'Dost')}
function personalCard(){const c=wellnessContext();return `<section class="card"><p class="eyebrow">YOUR PERSONAL CONTEXT</p><h2>${esc(addressUser())}, tumhare goals ke hisaab se</h2><p>${fmt(c.weight)} kg · ${fmt(c.height)} cm · ${fmt(c.age)} years · ${esc(c.sex==='male'?'Male':c.sex==='female'?'Female':'Not specified')} · Target ${fmt(c.targetWeight)} kg</p><div class="grid2"><div><small>Calories remaining (app target)</small><div class="stat">${fmt(Math.max(0,c.kcal-c.loggedKcal))} kcal</div></div><div><small>Protein remaining</small><div class="stat">${fmt(Math.max(0,c.protein-c.loggedProtein))} g</div></div></div><small>${profileSharing()?'Profile summary AI ke saath share hogi (name/email nahi).':'Ye personal details app mein hi rehti hain. AI reply general hoga; neeche tumhare targets se comparison milega.'}</small>${c.bmi<18.5?'<p class="notice">BMI low range mein hai. Weight gain targets ko clinician/dietitian se review karwana achha rahega.</p>':''}</section>`}
function planComparison(r){const c=wellnessContext();return `<p class="notice">${esc(addressUser())}, tumhara daily target ${fmt(c.kcal)} kcal aur ${fmt(c.protein)} g protein hai. ${r.totals.kcal==null?'Plan calories unknown.':`Is plan mein estimated ${fmt(r.totals.kcal)} kcal hain (${fmt(Math.abs(c.kcal-r.totals.kcal))} kcal ${r.totals.kcal<c.kcal?'kam':'zyada'}).`} ${r.totals.protein==null?'':`Protein estimate ${fmt(r.totals.protein)} g hai.`} Targets estimates hain; zarurat ke hisaab se review karo.</p>`}
function wellnessConsent(mode){return `${aiNotice(mode)}<small>${profileSharing()?'Personal nutrition summary included with your saved permission.':'Personal summary stays in the app. Full AI personalization requires paid service and opt-in in Profile.'} Each request uses the existing daily allowance. Replies are temporary.</small>`}
function coachView(){const d=wellnessDraft.coach||{},r=wellnessResult.coach;return `<div class="row"><h1>AI Personal Coach</h1>${btn('‹ Home','tab','chip','data-id="home"')}</div><p class="muted">Balanced meals, habits aur nutrition ke baare mein pucho.</p>${personalCard()}<section class="card stack"><textarea id="coachQuestion" maxlength="1500" placeholder="Protein ka target kaise complete karun?">${esc(d.question||'')}</textarea>${wellnessConsent('coach')}${btn(wellnessBusy?'Thinking…':'✦ Ask coach','coachAsk','primary wide',wellnessBusy?'disabled':'')}</section>${r?`<section class="card"><p class="eyebrow">AI COACH RESPONSE</p><p class="v4-answer">${esc(addressUser())}, ${esc(r.answer)}</p><p class="notice">${esc(r.caution||'General guidance, not medical advice.')}</p></section>`:''}`}
function plannerView(){const d=wellnessDraft.planner||{},r=wellnessResult.planner;return `<div class="row"><h1>Budget diet planner</h1>${btn('‹ Home','tab','chip','data-id="home"')}</div><p class="muted">Ek din ka Indian diet plan, estimated budget ke saath.</p>${personalCard()}<section class="card stack">${label('Daily budget (₹)',input('budget',d.budget??100,'number','id="planBudget" min="20" max="10000"'))}${label('Diet preference',select('diet',[['mixed','Veg & non-veg'],['veg','Vegetarian'],['egg','Vegetarian + eggs'],['vegan','Vegan']],d.diet||'mixed'))}${label(profileSharing()?'Foods to avoid / allergies':'Ingredients to exclude (no personal medical details)',input('avoid',d.avoid||'','text','maxlength="300"'))}${wellnessConsent('planner')}${btn(wellnessBusy?'Planning…':'✦ Generate diet plan','plannerAsk','primary wide',wellnessBusy?'disabled':'')}</section>${r?`<section class="card"><p class="eyebrow">ESTIMATED ONE-DAY PLAN</p><h2>₹${r.totals.cost??'Unknown'} / ₹${r.budget}</h2><p class="notice">${r.withinBudget===false?'Estimated cost exceeds budget. Adjust budget or request alternatives.':r.withinBudget===null?'Some prices are missing; budget cannot be verified.':'Estimated total is within budget.'} Prices vary locally.</p>${r.meals.map(m=>`<div class="v4-item"><strong>${esc(m.name)} · ₹${m.cost??'—'}</strong><p>${esc(m.food)}</p><small>${m.kcal??'—'} kcal · P ${m.protein??'—'}g · C ${m.carbs??'—'}g · F ${m.fat??'—'}g</small></div>`).join('')}<p><strong>Daily estimate:</strong> ${r.totals.kcal??'—'} kcal · P ${r.totals.protein??'—'}g · C ${r.totals.carbs??'—'}g · F ${r.totals.fat??'—'}g</p>${planComparison(r)}<p class="v4-answer">${esc(r.notes)}</p><small>Verify ingredients and allergens independently. This is a suggestion, not an automatically logged meal or prescribed diet.</small></section>`:''}`}
async function runWellness(mode){if(wellnessBusy)return;if(demo)return toast('Live login and backend are required for AI.');const d={};if(mode==='coach'){d.question=$('#coachQuestion').value.trim();if(!d.question)return toast('Enter a question.')}else{d.budget=Number($('#planBudget').value);d.diet=$('[name=diet]').value;d.avoid=$('[name=avoid]').value;if(!Number.isFinite(d.budget)||d.budget<20||d.budget>10000)return toast('Budget must be ₹20–₹10,000.')}if(!allowAI())return;wellnessDraft[mode]=d;const shared=profileSharing();const payload={...d,context:shared?wellnessContext():{},profileConsent:shared,consent:true},epoch=wellnessEpoch;wellnessBusy=true;delete wellnessResult[mode];render();try{const r=await api('/'+mode,payload);if(epoch===wellnessEpoch)wellnessResult[mode]=r}catch(e){if(epoch===wellnessEpoch)toast(e.message)}finally{if(epoch===wellnessEpoch){wellnessBusy=false;if(tab===mode)render()}}}
function privacyView(){return `<p class="eyebrow">AI PRIVACY</p><small>AI permission: ${aiPermission().input?'Allowed on this device':'Not yet allowed'}. Profile sharing: ${profileSharing()?'On':'Off'}.</small>${btn('Reset AI permissions','aiPermissionReset','secondary wide')}${v4Status.privateContext?btn(profileSharing()?'Turn off AI profile sharing':'Allow AI profile sharing','aiProfileToggle','secondary wide'):'<small>Profile stays local in free mode. Full AI profile sharing requires paid service configuration.</small>'}<label class="inline-check"><input type="checkbox" id="activityOptout" ${s.prefs.activityOptout?'checked':''}>Opt out of identifiable activity statistics</label>${btn('Save activity privacy','privacySave','secondary wide')}${btn('Export food diary (CSV)','exportCSV','secondary wide')}${!demo?btn('Export backend account records (JSON)','exportBackend','secondary wide'):''}<small>Opt-out removes identifiable activity history, not necessary AI quota, push subscriptions or aggregate service metrics. Exports contain sensitive data; store securely. Existing account deletion remains available.</small>`}
async function savePrivacy(){const opt=$('#activityOptout').checked,epoch=wellnessEpoch;if(!demo)await api('/privacy',{activityOptout:opt});if(epoch!==wellnessEpoch)return;s.prefs.activityOptout=opt;activityDay='';redraw();toast('Activity privacy saved.')}
function downloadData(name,data,type){const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([data],{type}));link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}
function exportCSV(){const csv=v=>{let t=String(v??'');if(/^[\s]*[=+\-@]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'};const rows=[['Date','Meal','Food',...foodKeys]];for(const [date,d] of Object.entries(s.days).sort(([a],[b])=>a.localeCompare(b)))for(const f of d.food)rows.push([date,s.meals.find(m=>m.id===f.meal)?.name||f.meal,f.name,...foodKeys.map(k=>f[k])]);downloadData('MyBodyTrack-food-diary.csv',rows.map(r=>r.map(csv).join(',')).join('\r\n'),'text/csv;charset=utf-8')}

render();initFirebase().then(()=>{if(user||demo)deepLink()});if(location.protocol!=='file:'&&'serviceWorker'in navigator)getSW().catch(()=>{});
